--  DDL for Trigger TG_AUD_HBLT
--------------------------------------------------------

  CREATE OR REPLACE NONEDITIONABLE TRIGGER "NUPPA"."TG_AUD_HBLT" 
BEFORE UPDATE OR DELETE ON H_BOLETIM
FOR EACH ROW
DECLARE
  V_EVENTO_ID NUMBER(12);
  V_USU_BD VARCHAR2(128);
  V_USU_SO VARCHAR2(255);
BEGIN
  V_EVENTO_ID := NUPPA_AUDIT.SEQ_AUD_EVENTO.NEXTVAL;
  V_USU_BD := SYS_CONTEXT('USERENV', 'SESSION_USER');
  V_USU_SO := SYS_CONTEXT('USERENV', 'OS_USER');

  IF DELETING THEN
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_ID', TO_CHAR(:OLD.HBLT_ID, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), NULL,
      'D', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_NUM', TO_CHAR(:OLD.HBLT_NUM, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), NULL,
      'D', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_ANO', TO_CHAR(:OLD.HBLT_ANO, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), NULL,
      'D', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_DATA_LEV', TO_CHAR(:OLD.HBLT_DATA_LEV, 'YYYY-MM-DD HH24:MI:SS'), NULL,
      'D', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_DATA_CAD', TO_CHAR(:OLD.HBLT_DATA_CAD, 'YYYY-MM-DD HH24:MI:SS'), NULL,
      'D', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_DT_ENTRADA', TO_CHAR(:OLD.HBLT_DT_ENTRADA, 'YYYY-MM-DD HH24:MI:SS'), NULL,
      'D', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
  ELSE  -- UPDATING
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_ID', TO_CHAR(:OLD.HBLT_ID, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), TO_CHAR(:NEW.HBLT_ID, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''),
      'U', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_NUM', TO_CHAR(:OLD.HBLT_NUM, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), TO_CHAR(:NEW.HBLT_NUM, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''),
      'U', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_ANO', TO_CHAR(:OLD.HBLT_ANO, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), TO_CHAR(:NEW.HBLT_ANO, 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''),
      'U', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_DATA_LEV', TO_CHAR(:OLD.HBLT_DATA_LEV, 'YYYY-MM-DD HH24:MI:SS'), TO_CHAR(:NEW.HBLT_DATA_LEV, 'YYYY-MM-DD HH24:MI:SS'),
      'U', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
    NUPPA_AUDIT.PR_INSERE_AUDITORIA(V_EVENTO_ID, :OLD.HBLT_ID,
      'H_BOLETIM', 'HBLT_DATA_CAD', TO_CHAR(:OLD.HBLT_DATA_CAD, 'YYYY-MM-DD HH24:MI:SS'), TO_CHAR(:NEW.HBLT_DATA_CAD, 'YYYY-MM-DD HH24:MI:SS'),
      'U', CAST(SYSTIMESTAMP AS TIMESTAMP), V_USU_BD, V_USU_SO);
